event: response.output_text.done
data: {"type":"response.output_text.done","content_index":0,"item_id":"msg_0b94f2fb65fe274c016aee59deae2087d0b1415c5d5a2c4653","logprobs":[],"output_index":1,"sequence_number":1786,"text":"{\n  \"name\": {\n    \"text\": \"JANE Q. EXAMPLE, PharmD\",\n    \"lines\": [1]\n  },\n  \"contact\": [\n    {\n      \"text\": \"Calgary, Alberta | jane.example@example.com | 555-0100 | example.com/in/janeexample\",\n      \"lines\": [2]\n    },\n    {\n      \"text\": \"Authorized to work in Canada without sponsorship | Remote within Canada\",\n      \"lines\": [3]\n    }\n  ],\n  \"summary\": [\n    {\n      \"text\": \"Clinical informatics and life-sciences data product leader with 12 years of experience connecting scientific requirements with engineering and delivery. Background spans drug-reference products, terminology, data architecture, and hands-on software delivery.\",\n      \"lines\": [5]\n    }\n  ],\n  \"skills\": [\n    {\n      \"text\": \"**Product Delivery:** customer discovery, roadmap proposals, backlog ownership, requirements, user stories, acceptance criteria, release planning, demonstrations\",\n      \"lines\": [7]\n    },\n    {\n      \"text\": \"**Data Products:** reference data, terminology, canonical records, entity resolution, data quality, schema mapping, lineage, provenance, data catalogs\",\n      \"lines\": [8]\n    },\n    {\n      \"text\": \"**Engineering:** SQL, Python, Ruby, ETL pipelines, REST APIs, PostgreSQL, Neo4j, automated testing, continuous integration\",\n      \"lines\": [9]\n    },\n    {\n      \"text\": \"**Bounded Familiarity:** Databricks and PySpark familiarity with no production implementation; applied master-data patterns without enterprise MDM platform implementation\",\n      \"lines\": [10]\n    }\n  ],\n  \"roles\": [\n    {\n      \"organisation\": {\n        \"text\": \"Meridian Drug Knowledge\",\n        \"lines\": [12]\n      },\n      \"title\": {\n        \"text\": \"Reference Data Squad, Product Owner\",\n        \"lines\": [13]\n      },\n      \"title_of_record\": {\n        \"text\": \"Clinical Data Engineer - Life Sciences\",\n        \"lines\": [14]\n      },\n      \"dates\": {\n        \"text\": \"March 2023 to September 2025\",\n        \"lines\": [15]\n      },\n      \"location\": {\n        \"text\": \"Calgary, Alberta (Remote)\",\n        \"lines\": [15]\n      },\n      \"context\": [\n        {\n          \"text\": \"Partnered with scientists, customer teams, and engineers on a drug and clinical-reference platform while remaining hands-on in the production codebase.\",\n          \"lines\": [16]\n        }\n      ],\n      \"bullets\": [\n        {\n          \"text\": \"Owned the team backlog and wrote epics, user stories, acceptance criteria, and demonstrations for clinical-data and reference-data capabilities\",\n          \"lines\": [18]\n        },\n        {\n          \"text\": \"Gathered customer and scientific requirements, proposed roadmap priorities, and translated ambiguous domain needs into technical specifications for engineering and quality assurance\",\n          \"lines\": [19]\n        },\n        {\n          \"text\": \"Led delivery of a terminology classification service, defining review rules and measurable coverage while uncertain cases remained routed to scientific review\",\n          \"lines\": [20]\n        },\n        {\n          \"text\": \"Designed canonical-record and entity-resolution rules across drug, condition, protein, and clinical-trial sources, preserving source identifiers and provenance\",\n          \"lines\": [22]\n        },\n        {\n          \"text\": \"Built and maintained SQL, Python, and Ruby pipelines. They mapped, validated, and loaded external reference datasets into PostgreSQL and Neo4j\",\n          \"lines\": [23]\n        },\n        {\n          \"text\": \"Specified REST API payloads, schema mappings, validation rules, and backward-compatible releases for downstream customer integrations\",\n          \"lines\": [24]\n        },\n        {\n          \"text\": \"Documented data definitions, lineage, and data-quality constraints in a catalog used by engineering and customer teams\",\n          \"lines\": [25]\n        }\n      ]\n    },\n    {\n      \"organisation\": {\n        \"text\": \"National Formulary Cooperative\",\n        \"lines\": [26]\n      },\n      \"title\": {\n        \"text\": \"Director, Clinical Informatics\",\n        \"lines\": [27]\n      },\n      \"title_of_record\": null,\n      \"dates\": {\n        \"text\": \"March 2016 to February 2023\",\n        \"lines\": [28]\n      },\n      \"location\": {\n        \"text\": \"Chicago, Illinois (Remote)\",\n        \"lines\": [28]\n      },\n      \"context\": [\n        {\n          \"text\": \"Led technical delivery for national drug-information products by connecting pharmacy practice, editorial policy, and software teams.\",\n          \"lines\": [29]\n        }\n      ],\n      \"bullets\": [\n        {\n          \"text\": \"Managed roadmap proposals and publishing backlogs for drug-reference databases and APIs under an informatics title\",\n          \"lines\": [30]\n        },\n        {\n          \"text\": \"Authored functional requirements, workflow specifications, validation rules, and acceptance criteria for publishing and customer-integration changes\",\n          \"lines\": [31]\n        },\n        {\n          \"text\": \"Designed dimensional data models and SQL transformations for drug classifications, terminology mappings, and product-quality reporting\",\n          \"lines\": [32]\n        },\n        {\n          \"text\": \"Presented product demonstrations and technical recommendations to clinical editors, customers, engineering teams, and organizational leadership\",\n          \"lines\": [33]\n        }\n      ]\n    },\n    {\n      \"organisation\": {\n        \"text\": \"Cascade Valley Health System\",\n        \"lines\": [34]\n      },\n      \"title\": {\n      